import{_ as i,o as s,c as l,a3 as t,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/vorbereitung/zeugnisbemerkungen-bemerkungsart.png",a="/bilder/vorbereitung/bemerkungsart.png",g="/bilder/vorbereitung/bemerkung-eintragen.png",f=JSON.parse('{"title":"Zeugnisbemerkungen für eine Schülergruppe erfassen","description":"","frontmatter":{"title":"Zeugnisbemerkungen für eine Schülergruppe erfassen","source_pageid":398,"source_revision":3253},"headers":[],"relativePath":"zeugnisse/vorbereitung/zeugnisbemerkungen-eintragen-gruppenprozesse-noten-zeugnisvorbereitung.md","filePath":"zeugnisse/vorbereitung/zeugnisbemerkungen-eintragen-gruppenprozesse-noten-zeugnisvorbereitung.md"}'),o={name:"zeugnisse/vorbereitung/zeugnisbemerkungen-eintragen-gruppenprozesse-noten-zeugnisvorbereitung.md"};function d(c,r,m,h,b,p){return s(),l("div",null,[...r[0]||(r[0]=[t('<h1 id="zeugnisbemerkungen-fur-eine-schulergruppe-erfassen" tabindex="-1">Zeugnisbemerkungen für eine Schülergruppe erfassen <a class="header-anchor" href="#zeugnisbemerkungen-fur-eine-schulergruppe-erfassen" aria-label="Permalink to &quot;Zeugnisbemerkungen für eine Schülergruppe erfassen&quot;">​</a></h1><p><a href="/bilder/vorbereitung/zeugnisbemerkungen-bemerkungsart.png"><img src="'+u+'" alt="Bemerkungsarten einschließlich Allgemeine Entwicklung" loading="lazy"></a></p><p><em>Bemerkungsarten einschließlich Allgemeine Entwicklung — Oberfläche von SchILD-NRW 3.6.0.</em></p><p>Wählen Sie die Bemerkungsart und entscheiden Sie, ob vorhandene Texte erhalten bleiben. Anschließend erfassen Sie den gemeinsamen Text frei oder mit Floskeln.</p><p>Dieser Gruppenprozess ist geeignet, um für eine Gruppe <em>Bemerkungen</em> für das Zeugnis einzutragen. Dies ist sinnvoll, wenn eine größere Gruppe von Schülerinnen oder Schülern z.B. an einem Wettbewerb oder Betriebspraktikum teilgenommen haben und dies auf dem Zeugnis bescheinigt werden soll.</p><p><a href="/bilder/vorbereitung/bemerkungsart.png"><img src="'+a+'" alt="Die Arten an setzbaren Bemerkungen." loading="lazy"></a></p><p><em>Die Arten an setzbaren Bemerkungen.</em></p><h2 id="_1-bemerkungsart-und-erhalt-vorhandener-texte-wahlen" tabindex="-1">1. Bemerkungsart und Erhalt vorhandener Texte wählen <a class="header-anchor" href="#_1-bemerkungsart-und-erhalt-vorhandener-texte-wahlen" aria-label="Permalink to &quot;1. Bemerkungsart und Erhalt vorhandener Texte wählen&quot;">​</a></h2><p>Nach Aufruf des Prozesses muss ausgewählt werden, um welche Bemerkungsart es sich handelt. Zur Verfügung stehen:</p><ul><li>Zeugnisbemerkung</li><li>Arbeits- und Sozialverhalten</li><li>Außerunterrichtliches Engagement</li><li>Bemerkung zum Förderschwerpunkt</li><li>Bemerkung zur Versetzung</li><li>Lernentwicklung und Leistungsstand (Allgemeine Lernentwicklung)</li></ul><p>Neben der Auswahl der Art der Bemerkung können an dieser Stelle noch zusätzliche Einstellungen vorgenommen werden:</p><ul><li>vorhandene Bemerkungen sollen erhalten bleiben</li><li>Neue Bemerkung mit Zeilenumbruch erzeugen</li></ul>',12),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,'Standardmäßig ist das Häkchen bei "vorhandene Bemerkungen sollen erhalten bleiben" gesetzt, sodass bereits eingegebene Bemerkungen nicht überschrieben werden.')],-1),e("p",null,[n("Bestätigen Sie mit "),e("strong",null,"OK"),n(" um fortzufahren.")],-1),e("p",null,[e("a",{href:"/bilder/vorbereitung/bemerkung-eintragen.png"},[e("img",{src:g,alt:"Bemerkungen eintragen",loading:"lazy"})])],-1),e("p",null,[e("em",null,"Bemerkungen eintragen")],-1),e("h2",{id:"_2-bemerkungen-eingeben-oder-floskeln-verwenden",tabindex:"-1"},[n("2. Bemerkungen eingeben oder Floskeln verwenden "),e("a",{class:"header-anchor",href:"#_2-bemerkungen-eingeben-oder-floskeln-verwenden","aria-label":'Permalink to "2. Bemerkungen eingeben oder Floskeln verwenden"'},"​")],-1),e("p",null,"Im sich nun öffnenden Fenster werden die Bemerkungen eingetragen.",-1),e("p",null,"Hierbei können die Bemerkungen sowohl händisch, per Klick aus der unten stehenden Floskelliste als auch durch Eingabe des Kürzels und anschließendem Drücken der Enter-Taste eingegeben werden.",-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Die Bearbeitung der Floskeln läuft über den Reiter "),e("em",null,"Kataloge ➜ Floskeln bearbeiten"),n(" ab.")])],-1),e("p",null,[n("Die Übernahme der Bemerkungen erfolgt durch Klicken auf die Schaltfläche "),e("strong",null,"OK"),n(".")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Zeugnisbemerkungen_eintragen_(Gruppenprozesse_Noten,_Zeugnisvorbereitung)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 3253.")],-1)])])}const v=i(o,[["render",d]]);export{f as __pageData,v as default};
